export function coalesceRanges(ranges) {
  if (!Array.isArray(ranges) || ranges.some(r => !Array.isArray(r) || r.length !== 2 || r.some(n => !Number.isSafeInteger(n) || n < 0) || r[0] > r[1])) throw new TypeError('range');
  const result = [];
  for (const [start,end] of ranges.map(r => [...r]).sort((a,b) => a[0]-b[0] || a[1]-b[1])) {
    const last = result.at(-1);
    if (last && start <= last[1]) last[1] = Math.max(last[1], end);
    else result.push([start,end]);
  }
  return result;
}

export function takeUtf8Prefix(text, maxBytes) {
  if (typeof text !== 'string' || !Number.isSafeInteger(maxBytes) || maxBytes < 0) throw new TypeError('input');
  let result = '', bytes = 0;
  for (const point of text) {
    const size = new TextEncoder().encode(point).length;
    if (bytes + size > maxBytes) break;
    result += point; bytes += size;
  }
  return result;
}

export function uniqueReplacement(text, oldText, newText) {
  if ([text,oldText,newText].some(x => typeof x !== 'string') || !oldText.length) throw new TypeError('input');
  const first = text.indexOf(oldText);
  if (first < 0 || first !== text.lastIndexOf(oldText)) throw new RangeError('match');
  return text.slice(0,first) + newText + text.slice(first + oldText.length);
}

export function planReadyTasks(tasks, completedIds) {
  if (!Array.isArray(tasks) || !Array.isArray(completedIds)) throw new TypeError('input');
  const ids = new Set();
  for (const t of tasks) { if (!t || typeof t.id !== 'string' || !t.id || ids.has(t.id) || !Array.isArray(t.dependsOn)) throw new TypeError('task'); ids.add(t.id); }
  if (new Set(completedIds).size !== completedIds.length || completedIds.some(id => !ids.has(id))) throw new TypeError('completed');
  for (const t of tasks) if (new Set(t.dependsOn).size !== t.dependsOn.length || t.dependsOn.some(id => !ids.has(id))) throw new TypeError('dependency');
  const byId = new Map(tasks.map(t => [t.id,t])), visiting = new Set(), visited = new Set();
  function visit(id) { if (visiting.has(id)) throw new TypeError('cycle'); if (visited.has(id)) return; visiting.add(id); for (const dep of byId.get(id).dependsOn) visit(dep); visiting.delete(id); visited.add(id); }
  for (const id of ids) visit(id);
  const done = new Set(completedIds);
  return tasks.filter(t => !done.has(t.id) && t.dependsOn.every(id => done.has(id))).map(t => t.id);
}

export function resolveScopedPath(path) {
  if (typeof path !== 'string') throw new TypeError('path');
  const parts = path.split('/');
  if (parts.length < 2 || !['src','docs'].includes(parts[0]) || parts.some(p => !/^[A-Za-z0-9_.-]+$/.test(p) || ['.','..','.git','node_modules'].includes(p.toLowerCase()))) throw new TypeError('path');
  return path;
}

export function applyUpdates(rows, updates) {
  const valid = (x,field) => x && typeof x.id === 'string' && x.id.length > 0 && Number.isSafeInteger(x[field]) && x[field] > 0 && Object.hasOwn(x,'value');
  if (!Array.isArray(rows) || !Array.isArray(updates) || rows.some(r => !valid(r,'version')) || updates.some(u => !valid(u,'expectedVersion')) || new Set(rows.map(r => r.id)).size !== rows.length) throw new TypeError('input');
  const byId = new Map(rows.map(r => [r.id,r])), changed = new Map();
  for (const u of updates) { const row = byId.get(u.id); if (!row || changed.has(u.id) || row.version !== u.expectedVersion || row.version === Number.MAX_SAFE_INTEGER) return {ok:false,conflict:u.id,rows}; changed.set(u.id,{...row,version:row.version+1,value:u.value}); }
  return {ok:true,conflict:null,rows:rows.map(r => changed.get(r.id) ?? r)};
}
